            'subgrid': subgrid,
            'h': max_r - min_r + 1,
            'w': max_c - min_c + 1,
            'px': px
        })

print("Component shapes sorted by px desc:")
component_shapes_sorted = sorted(component_shapes, key=lambda x: x['px'], reverse=True)
for s in component_shapes_sorted:
    print(f"  px={s['px']}, size={s['h']}x{s['w']}, color={s['color']}")

# HORIZONTAL packing - place each shape next to previous one, same height as tallest
max_h = max(s['h'] for s in component_shapes_sorted)
total_w = sum(s['w'] for s in component_shapes_sorted)

output = [[0]*total_w for _ in range(max_h)]
cur_r, cur_c = 0, 0

for s in component_shapes_sorted:
    sr = s['subgrid']
    ph, pw = s['h'], s['w']

    # Center vertically or top-align? Try top-align first
    start_y = (max_h - ph) // 2

    for y in range(ph):
        for x in range(pw):
            output[start_y + y][cur_c + x] = sr[y][x]

    cur_c += pw  # Move to next column position

print(f"\nOutput shape: {max_h}x{total_w}")
for row in output:
    print(row)

submit_data = {"action": "submit", "grid": output}
print(json.dumps(submit_data))
